WITH RecentEmployees AS (SELECT * FROM employees WHERE is_remote = FALSE), agg AS (SELECT CASE WHEN salary >= 124000 THEN 'high' WHEN salary >= 67000 THEN 'mid' ELSE 'low' END AS salary_bucket, ROUND((100 * SUM(CASE WHEN job_title = 'Manager' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_manager FROM RecentEmployees GROUP BY CASE WHEN salary >= 124000 THEN 'high' WHEN salary >= 67000 THEN 'mid' ELSE 'low' END) SELECT salary_bucket, pct_manager FROM agg ORDER BY 2;
